//! Human-readable output: console summary, ANALYSIS.md and MIGRATION.md.

use crate::mapping;
use crate::model::{Report, SymbolKind};
use crate::plan::Plan;
use crate::scaffold::Manifest;
use std::fmt::Write as _;

fn md_escape(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}

pub fn analysis_markdown(r: &Report) -> String {
    let mut s = String::new();
    let _ = writeln!(s, "# Analysis: {}\n", r.project_name);
    let _ = writeln!(
        s,
        "Generated by convert-to-rust (c2r) v{} from `{}` ({}).\n",
        r.tool_version, r.target, r.input_kind
    );
    s.push_str("## Overview\n\n| Metric | Value |\n|---|---|\n");
    let _ = writeln!(
        s,
        "| Primary language | {} |",
        r.primary_language.map(|l| l.name()).unwrap_or("-")
    );
    let _ = writeln!(
        s,
        "| Frameworks | {} |",
        if r.frameworks.is_empty() {
            "-".into()
        } else {
            r.frameworks.join(", ")
        }
    );
    let _ = writeln!(s, "| Source files analysed | {} |", r.files.len());
    let _ = writeln!(s, "| Code lines | {} |", r.total_code_lines());
    let _ = writeln!(
        s,
        "| Symbols (functions, methods, types) | {} |",
        r.total_symbols()
    );
    let _ = writeln!(s, "| HTTP routes | {} |", r.all_routes().len());
    let _ = writeln!(s, "| Dependencies | {} |", r.dependencies.len());
    let _ = writeln!(s, "| Binaries | {} |", r.binaries.len());
    if !r.bytecode_classes.is_empty() {
        let _ = writeln!(
            s,
            "| JVM classes (bytecode) | {} |",
            r.bytecode_classes.len()
        );
    }
    let _ = writeln!(
        s,
        "| Other / skipped files | {} / {} |\n",
        r.other_files, r.skipped_files
    );

    if !r.languages.is_empty() {
        s.push_str(
            "## Languages\n\n| Language | Files | Lines | Code lines |\n|---|---:|---:|---:|\n",
        );
        let mut langs: Vec<_> = r.languages.iter().collect();
        langs.sort_by_key(|l| std::cmp::Reverse(l.1.code_lines));
        for (name, st) in langs {
            let _ = writeln!(
                s,
                "| {name} | {} | {} | {} |",
                st.files, st.lines, st.code_lines
            );
        }
        s.push('\n');
    }

    if !r.entry_points.is_empty() {
        s.push_str("## Entry points\n\n");
        for e in &r.entry_points {
            let _ = writeln!(s, "- `{e}`");
        }
        s.push('\n');
    }

    let routes = r.all_routes();
    if !routes.is_empty() {
        s.push_str("## HTTP routes\n\n| Method | Path | Handler | Framework | Location |\n|---|---|---|---|---|\n");
        for (f, rt) in routes {
            let _ = writeln!(
                s,
                "| {} | `{}` | {} | {} | `{}:{}` |",
                rt.method,
                md_escape(&rt.path),
                rt.handler
                    .as_deref()
                    .map(|h| format!("`{h}`"))
                    .unwrap_or_else(|| "(inline)".into()),
                rt.framework,
                f.path,
                rt.line
            );
        }
        s.push('\n');
    }

    let types: Vec<_> = r
        .files
        .iter()
        .flat_map(|f| {
            f.symbols
                .iter()
                .filter(|x| {
                    matches!(
                        x.kind,
                        SymbolKind::Class
                            | SymbolKind::Struct
                            | SymbolKind::Interface
                            | SymbolKind::Enum
                    )
                })
                .map(move |x| (f, x))
        })
        .collect();
    if !types.is_empty() {
        s.push_str(
            "## Types\n\n| Type | Kind | Fields | Bases | Location |\n|---|---|---:|---|---|\n",
        );
        for (f, t) in types.iter().take(300) {
            let _ = writeln!(
                s,
                "| `{}` | {:?} | {} | {} | `{}:{}` |",
                t.name,
                t.kind,
                t.fields.len(),
                md_escape(&t.bases.join(", ")),
                f.path,
                t.line
            );
        }
        if types.len() > 300 {
            let _ = writeln!(
                s,
                "\n... and {} more (see c2r-report.json).",
                types.len() - 300
            );
        }
        s.push('\n');
    }

    let mut files: Vec<_> = r
        .files
        .iter()
        .filter(|f| f.language.is_portable())
        .collect();
    files.sort_by_key(|f| std::cmp::Reverse(f.code_lines));
    if !files.is_empty() {
        s.push_str("## Modules (largest first)\n\n| File | Language | Code lines | Functions | Methods | Types | Imports |\n|---|---|---:|---:|---:|---:|---:|\n");
        for f in files.iter().take(200) {
            let count = |k: SymbolKind| f.symbols.iter().filter(|x| x.kind == k).count();
            let types = f
                .symbols
                .iter()
                .filter(|x| {
                    matches!(
                        x.kind,
                        SymbolKind::Class
                            | SymbolKind::Struct
                            | SymbolKind::Interface
                            | SymbolKind::Enum
                    )
                })
                .count();
            let tag = if f.is_test {
                " (test)"
            } else if f.is_entry {
                " (entry)"
            } else {
                ""
            };
            let _ = writeln!(
                s,
                "| `{}`{tag} | {} | {} | {} | {} | {} | {} |",
                f.path,
                f.language.name(),
                f.code_lines,
                count(SymbolKind::Function),
                count(SymbolKind::Method),
                types,
                f.imports.len()
            );
        }
        s.push('\n');
    }

    if !r.module_graph.is_empty() {
        s.push_str("## Internal dependency graph\n\n```mermaid\ngraph LR\n");
        let mut ids = std::collections::BTreeMap::new();
        for (a, b) in r.module_graph.iter().take(150) {
            let n = ids.len();
            let ia = *ids.entry(a.clone()).or_insert(n);
            let n = ids.len();
            let ib = *ids.entry(b.clone()).or_insert(n);
            let _ = writeln!(
                s,
                "  m{ia}[\"{}\"] --> m{ib}[\"{}\"]",
                a.replace('"', "'"),
                b.replace('"', "'")
            );
        }
        s.push_str("```\n\n");
    }

    let mapped = mapping::map_dependencies(r);
    if !mapped.is_empty() {
        s.push_str("## Dependencies and Rust equivalents\n\n| Dependency | Ecosystem | Category | Rust crate(s) | Note |\n|---|---|---|---|---|\n");
        for m in &mapped {
            let crates = if m.crates.is_empty() {
                "**no mapping - review**".to_string()
            } else {
                m.crates
                    .iter()
                    .map(|c| format!("`{}`", c.name))
                    .collect::<Vec<_>>()
                    .join(", ")
            };
            let dev = if m.dev { " (dev)" } else { "" };
            let _ = writeln!(
                s,
                "| `{}`{dev} | {} | {} | {crates} | {} |",
                m.source,
                m.ecosystem,
                m.category.map(|c| c.label()).unwrap_or("-"),
                md_escape(&m.note)
            );
        }
        s.push('\n');
    }
    let hints = mapping::std_hints_for(r);
    if !hints.is_empty() {
        s.push_str("## Standard library usage\n\n");
        for h in hints {
            let _ = writeln!(s, "- {} `{}` -> {}", h.lang.name(), h.module, h.rust);
        }
        s.push('\n');
    }

    let concepts = r.concept_totals();
    if !concepts.is_empty() {
        s.push_str("## Language features that need translation care\n\n| Feature | Occurrences |\n|---|---:|\n");
        let mut c: Vec<_> = concepts
            .into_iter()
            .filter(|(k, _)| mapping::concept_guidance(k).is_some())
            .collect();
        c.sort_by_key(|x| std::cmp::Reverse(x.1));
        for (k, n) in c {
            let _ = writeln!(
                s,
                "| {} | {n} |",
                mapping::concept_guidance(&k).map(|g| g.0).unwrap_or(&k)
            );
        }
        s.push('\n');
    }

    for b in &r.binaries {
        let _ = writeln!(s, "## Binary: `{}`\n", b.path);
        let _ = writeln!(
            s,
            "- Format: {} ({} {}-bit), {} bytes",
            b.format, b.arch, b.bits, b.size
        );
        let _ = writeln!(
            s,
            "- Toolchain: {}",
            if b.toolchain.is_empty() {
                "not identified".into()
            } else {
                b.toolchain.join("; ")
            }
        );
        if !b.libraries.is_empty() {
            let _ = writeln!(
                s,
                "- Linked libraries: {}",
                b.libraries
                    .iter()
                    .map(|l| format!("`{l}`"))
                    .collect::<Vec<_>>()
                    .join(", ")
            );
        }
        if !b.imported_symbols.is_empty() {
            let _ = writeln!(
                s,
                "- Imports ({}): {}",
                b.imported_symbols.len(),
                b.imported_symbols
                    .iter()
                    .take(40)
                    .map(|l| format!("`{l}`"))
                    .collect::<Vec<_>>()
                    .join(", ")
            );
        }
        if !b.exported_symbols.is_empty() {
            let _ = writeln!(
                s,
                "- Exports ({}): {}",
                b.exported_symbols.len(),
                b.exported_symbols
                    .iter()
                    .take(40)
                    .map(|l| format!("`{l}`"))
                    .collect::<Vec<_>>()
                    .join(", ")
            );
        }
        if !b.interesting_strings.is_empty() {
            s.push_str("- Interesting strings:\n");
            for st in b.interesting_strings.iter().take(30) {
                let _ = writeln!(s, "  - `{}`", st.replace('`', "'"));
            }
        }
        s.push('\n');
    }
    if !r.bytecode_classes.is_empty() {
        s.push_str("## JVM classes found\n\n");
        for c in r.bytecode_classes.iter().take(100) {
            let _ = writeln!(s, "- `{c}`");
        }
        if r.bytecode_classes.len() > 100 {
            let _ = writeln!(s, "- ... and {} more", r.bytecode_classes.len() - 100);
        }
        s.push('\n');
    }
    s
}

pub fn plan_markdown(r: &Report, plan: &Plan, manifest: Option<&Manifest>) -> String {
    let mut s = String::new();
    let _ = writeln!(s, "# Migration plan: {} -> Rust\n", r.project_name);
    let _ = writeln!(s, "## Strategy\n\n{}\n", plan.strategy);
    if !plan.target_architecture.is_empty() {
        s.push_str("## Target architecture\n\n");
        for a in &plan.target_architecture {
            let _ = writeln!(s, "- {a}");
        }
        s.push('\n');
    }
    if !plan.phases.is_empty() {
        let _ = writeln!(s, "## Phases\n\nRough effort: **~{:.0} hours** for a developer new to the codebase (heuristic: lines of code, symbol count, risky features). AI-assisted translation with `c2r translate` typically removes most of the mechanical work; review and testing remain.\n", plan.total_hours);
        for p in &plan.phases {
            let hours: f32 = p.modules.iter().map(|m| m.effort_hours).sum();
            let _ = writeln!(s, "### Phase {}: {} (~{:.1} h)\n", p.number, p.title, hours);
            s.push_str("| Original | Rust module | Lines | Symbols | Est. h | Notes |\n|---|---|---:|---:|---:|---|\n");
            for m in &p.modules {
                let rust = manifest
                    .and_then(|mf| mf.modules.iter().find(|x| x.source == m.path))
                    .map(|x| format!("`{}`", x.rust_file))
                    .unwrap_or_else(|| "-".into());
                let mut notes = m.risks.clone();
                if m.in_cycle {
                    notes.push("circular import".into());
                }
                let _ = writeln!(
                    s,
                    "| `{}` | {rust} | {} | {} | {:.2} | {} |",
                    m.path,
                    m.code_lines,
                    m.symbols,
                    m.effort_hours,
                    notes.join("; ")
                );
            }
            s.push('\n');
        }
    }

    let mapped = mapping::map_dependencies(r);
    let useful: Vec<_> = mapped.iter().filter(|m| !m.crates.is_empty()).collect();
    if !useful.is_empty() {
        s.push_str("## Library mapping\n\n| Original | Rust | Why / how |\n|---|---|---|\n");
        for m in useful {
            let crates = m
                .crates
                .iter()
                .map(|c| {
                    if c.features.is_empty() {
                        format!("`{} {}`", c.name, c.version)
                    } else {
                        format!("`{} {}` ({})", c.name, c.version, c.features.join(", "))
                    }
                })
                .collect::<Vec<_>>()
                .join(", ");
            let _ = writeln!(s, "| `{}` | {crates} | {} |", m.source, md_escape(&m.note));
        }
        s.push('\n');
    }
    if !plan.unmapped_dependencies.is_empty() {
        s.push_str("## Dependencies without a known mapping\n\nResearch a crate on crates.io / lib.rs, call the service's REST API with reqwest, or re-implement:\n\n");
        for u in &plan.unmapped_dependencies {
            let _ = writeln!(s, "- `{u}`");
        }
        s.push('\n');
    }
    if !plan.concepts.is_empty() {
        s.push_str("## Translating language concepts\n\n");
        for c in &plan.concepts {
            let _ = writeln!(
                s,
                "- **{}** ({} occurrences): {}",
                c.title, c.occurrences, c.guidance
            );
        }
        s.push('\n');
    }
    if !plan.binary_notes.is_empty() {
        s.push_str("## Binaries\n\n");
        for b in &plan.binary_notes {
            let _ = writeln!(s, "- {b}");
        }
        s.push('\n');
    }
    s.push_str("## Definition of done\n\n- [ ] Every `todo!()` replaced (`grep -rn 'todo!' src/` is empty)\n- [ ] `cargo clippy -- -D warnings` is clean and the `#![allow(...)]` in main.rs is removed\n- [ ] Original tests ported to `#[cfg(test)]` / `tests/` and passing\n- [ ] Same responses as the original for recorded real-world inputs (golden tests)\n- [ ] `serde_json::Value` placeholders replaced by concrete types\n- [ ] Load test shows the expected latency / memory win\n");
    s
}

pub fn print_summary(r: &Report, plan: &Plan) {
    println!("\nconvert-to-rust: {} ({})", r.project_name, r.input_kind);
    println!("{}", "-".repeat(60));
    let lang = r.primary_language.map(|l| l.name()).unwrap_or("-");
    println!("  Primary language : {lang}");
    if !r.frameworks.is_empty() {
        println!("  Frameworks       : {}", r.frameworks.join(", "));
    }
    let mut langs: Vec<_> = r.languages.iter().collect();
    langs.sort_by_key(|l| std::cmp::Reverse(l.1.code_lines));
    let summary: Vec<String> = langs
        .iter()
        .take(5)
        .map(|(n, s)| format!("{n} {}", s.code_lines))
        .collect();
    if !summary.is_empty() {
        println!(
            "  Code lines       : {} ({})",
            r.total_code_lines(),
            summary.join(", ")
        );
    }
    println!("  Files analysed   : {}", r.files.len());
    let fns = r
        .files
        .iter()
        .flat_map(|f| &f.symbols)
        .filter(|s| matches!(s.kind, SymbolKind::Function | SymbolKind::Method))
        .count();
    let types = r.total_symbols() - fns;
    println!("  Functions/methods: {fns}");
    println!("  Types            : {types}");
    println!("  HTTP routes      : {}", r.all_routes().len());
    if !r.entry_points.is_empty() {
        let shown: Vec<&str> = r.entry_points.iter().take(4).map(String::as_str).collect();
        let more = if r.entry_points.len() > 4 {
            format!(" (+{} more)", r.entry_points.len() - 4)
        } else {
            String::new()
        };
        println!("  Entry points     : {}{more}", shown.join(", "));
    }
    let mapped = mapping::map_dependencies(r);
    let hit = mapped
        .iter()
        .filter(|m| !m.crates.is_empty() && m.ecosystem != "import")
        .count();
    let via_imports = mapped.iter().filter(|m| m.ecosystem == "import").count();
    let extra = if via_imports > 0 {
        format!(", +{via_imports} detected from imports")
    } else {
        String::new()
    };
    println!(
        "  Dependencies     : {} ({} mapped to Rust crates{extra})",
        r.dependencies.len(),
        hit
    );
    for b in &r.binaries {
        println!(
            "  Binary           : {} - {} {} {}",
            b.path,
            b.format,
            b.arch,
            if b.toolchain.is_empty() {
                String::new()
            } else {
                format!("[{}]", b.toolchain.join(", "))
            }
        );
    }
    if !r.bytecode_classes.is_empty() {
        println!("  JVM classes      : {}", r.bytecode_classes.len());
    }
    if !plan.phases.is_empty() {
        println!(
            "  Migration plan   : {} phase(s), ~{:.0} h estimated",
            plan.phases.len(),
            plan.total_hours
        );
    }
    let top: Vec<String> = plan
        .concepts
        .iter()
        .take(4)
        .map(|c| c.title.clone())
        .collect();
    if !top.is_empty() {
        println!("  Watch out for    : {}", top.join("; "));
    }
}
